mapper.select:
SELECT descripcion, peso, alto, ancho, profundidad, idPaquete, noGuia, p.idEnvio
FROM paquete p
INNER JOIN envio e ON e.idEnvio= p.idEnvio;

mapper.update:
UPDATE paquete
SET descripcion= #{descripcion}, peso=#{peso}, alto=#{alto}, ancho=#{ancho}, profundidad=#{profundidad}
WHERE idPaquete=#{idPaquete};
